from abc import ABC, abstractmethod
from dirhunt.pool import Pool


class Source(ABC, Pool):
    """
    Abstract base class for all source implementations.
    Defines the contract for sources that feed URLs into the crawler.
    """

    @abstractmethod
    def add_domain(self, domain):
        """Add a domain to be scanned by this source."""
        pass

    @abstractmethod
    def callback(self, result):
        """Process a result from the source (e.g., a discovered URL)."""
        pass

    @abstractmethod
    def add_result(self, result):
        """Add a result to be processed later."""
        pass

    @abstractmethod
    def add_error(self, error):
        """Record an error encountered during scanning."""
        pass
